import sys,json,os
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
OUT='/app/output'
class Driver:
 def __init__(self):
  self.r=Robot(); self.s=self.r.spec(); self.o=self.r.observe(images=False); self.log=[]
  self.ps=np.array(self.s['arm']['position_m']); self.axes=np.array(self.s['arm']['axis']); self.ee=np.array(self.s['arm']['end_effector']['position_m'])
 def fk(self,q,point=None):
  T=np.eye(4)
  for p,a,v in zip(self.ps,self.axes,q):
   R=Rotation.from_rotvec(a*v).as_matrix(); A=np.eye(4); A[:3,:3]=R; A[:3,3]=p-R@p; T=T@A
  return (T[:3,:3]@(self.ee if point is None else point)+T[:3,3],T[:3,:3])
 def ik(self,p,R=None,q=None):
  q=np.array(self.o['proprio']['arm_pos'] if q is None else q)
  lo=np.array([-20,-2.24,-20,-2.57,-20,-2.09,-20]); hi=-lo
  def fun(v):
   pp,rr=self.fk(v)
   return np.r_[ (pp-p)*4, Rotation.from_matrix(rr.T@R).as_rotvec() if R is not None else (v-q)*.03 ]
  res=least_squares(fun,np.clip(q,lo+1e-6,hi-1e-6),bounds=(lo,hi),max_nfev=400)
  return res.x, np.linalg.norm(fun(res.x))
 def step(self,a,images=False):
  arr=np.array(a).reshape(-1,11); self.o=self.r.step('delta',arr.tolist(),images=images); self.log.extend(arr[:self.o.get('executed',len(arr))].tolist()); json.dump(self.log,open(OUT+'/trajectory.json','w')); return self.o
 def capture(self):
  self.o=self.r.observe();
  for k,v in self.o['images'].items(): Image.fromarray(v).save(OUT+'/'+k+'.png')
  np.savez(OUT+'/obs.npz',**self.o.get('depth',{})); json.dump(self.o['proprio'],open(OUT+'/proprio.json','w'))
  return {k:v for k,v in self.o.items() if k not in ['images','depth']}
 def move(self,q=None,base=None,grip=0,n=80):
  q=np.array(self.o['proprio']['arm_pos'] if q is None else q); base=np.array(self.o['proprio']['base_pose'] if base is None else base)
  for i in range(n):
   dq=q-np.array(self.o['proprio']['arm_pos']); db=base-np.array(self.o['proprio']['base_pose']); db[2]=(db[2]+np.pi)%(2*np.pi)-np.pi
   if np.max(abs(dq))<.003 and np.max(abs(db))<.002: break
   db[:2]*=min(1,.04/max(np.linalg.norm(db[:2]),1e-8)); db[2]=np.clip(db[2],-.06,.06)
   self.step(np.r_[db,np.clip(dq,-.065,.065),grip])
   if self.o['done']:break
  return self.capture()
 def command(self,c):
  op=c.pop('op')
  if op=='capture':return self.capture()
  if op=='fk':
   p,R=self.fk(self.o['proprio']['arm_pos']); return {'p':p.tolist(),'R':R.tolist()}
  if op=='ik':
   q,e=self.ik(np.array(c['p']),np.array(c['R']) if 'R' in c else None,c.get('q')); return {'q':q.tolist(),'error':e}
  if op=='pose':
   q,e=self.ik(np.array(c.pop('p')),np.array(c.pop('R')) if 'R' in c else None,c.pop('seed',None)); print(json.dumps({'ik_error':e,'q':q.tolist()}),flush=True); return self.move(q=q,**c)
  if op=='move':return self.move(**c)
  if op=='step':self.step(c['a']);return self.capture()
  if op=='hold': self.step(np.tile([0]*10+[c.get('grip',0)],(c.get('n',10),1)));return self.capture()
  if op=='reset': self.o=self.r.reset();self.log=[];json.dump([],open(OUT+'/trajectory.json','w'));return self.capture()
  if op=='status':return self.r.status()
if __name__=='__main__':
 if '--interactive' in sys.argv:
  d=Driver(); print('READY',flush=True)
  for line in sys.stdin:
   try: print(json.dumps(d.command(json.loads(line))),flush=True)
   except Exception as e:print(json.dumps({'error':str(e)}),flush=True)
 else:
  r=Robot()
  for a in json.load(open(OUT+'/trajectory.json')):
   o=r.step('delta',a,images=False)
   if o['done']: print(o['reason']);break
